n_h = numel(h_list);
method_name = {'LG-FWCCA', 'GL-FWCCA'};
nMeth=numel(method_name);

%% Extract avglocalvar and auc results for selecting bandwidth
LocalVariantsForselectbandwidth=cell(nMeth, nSNR);

for midx = 1:nMeth      % method index (1=LG, 2=GL)
  for sidx = 1:nSNR     % SNR index
       S = struct(...
            'AvgLocalVals', zeros(M, n_h), ...
            'AUCs_Train',   zeros(M, n_h) ...
           );
    LocalVariantsForselectbandwidth{midx, sidx} = S;
  end
end



for midx = 1:nMeth      % method index (1=LG, 2=GL)
  for sidx = 1:nSNR     % SNR index
      for m=1:M
         for h_idx=1:n_h
            LocalVariantsForselectbandwidth{midx, sidx}.AvgLocalVals(m, h_idx ...
                )=LocalWeightVariantresults{midx, sidx, m, h_idx}.AvgLocalVals;
            LocalVariantsForselectbandwidth{midx, sidx}.AUCs_Train(m, h_idx ...
                )=LocalWeightVariantresults{midx, sidx, m, h_idx}.AUCs_Train;
         end
      end
  end
end


%% Finding stable Index across each simulation for all snr level
% Thresholds
auc_thresh = 1e-3;
var_thresh = 1e-3;
LGStableIdx_Mat = NaN(M,nSNR); 
GLStableIdx_Mat = NaN(M,nSNR);
LGoptimalh_Mat = NaN(M,nSNR);  % pre-fill with NaN
GLoptimalh_Mat = NaN(M,nSNR);

for m=1:M
    
    for sidx=1:nSNR
       %fix mdix, sidx, find stable across h;
       %% ---- LG ----
       method_idx=1;
       LGaucAcrossh = LocalVariantsForselectbandwidth{method_idx, sidx}.AUCs_Train(m,:); %acess all h  
       LGvarAcrossh = LocalVariantsForselectbandwidth{method_idx, sidx}.AvgLocalVals(m,:); 
       
       LGdiff_auc = diff(LGaucAcrossh);
       LGdiff_var = diff(LGvarAcrossh);
       

       LGstable_auc_idx = find(abs(LGdiff_auc) < auc_thresh);

       if isempty(LGstable_auc_idx)
        LGstable_auc_idx = find(abs(LGdiff_auc) < 10*auc_thresh);
       end

       LGstable_var_idx = find(abs(LGdiff_var) < var_thresh);
       if isempty(LGstable_var_idx)
         LGstable_var_idx = find(abs(LGdiff_var) < 10 * var_thresh);
       end

       LGstable_idx = intersect(LGstable_var_idx, LGstable_auc_idx);

       if ~isempty(LGstable_idx)
         LGStableIdx_Mat(m, sidx) = min(LGstable_idx) + 1;
       else
         LGStableIdx_Mat(m, sidx) = min(LGstable_var_idx)+1;
       end
   
       LGoptimalh_Mat(m, sidx)=h_list(LGStableIdx_Mat(m, sidx)) ;

       %% ---- GL ----
       method_idx=2;
       GLaucAcrossh = LocalVariantsForselectbandwidth{method_idx, sidx}.AUCs_Train(m,:); 
       GLvarAcrossh = LocalVariantsForselectbandwidth{method_idx, sidx}.AvgLocalVals(m,:); 
       
       GLdiff_auc = diff(GLaucAcrossh);
       GLdiff_var = diff(GLvarAcrossh);

       GLstable_auc_idx = find(abs(GLdiff_auc) < auc_thresh);
       if isempty(GLstable_auc_idx)
         GLstable_auc_idx = find(abs(GLdiff_auc) < auc_thresh*10);
       end

       GLstable_var_idx = find(abs(GLdiff_var) < var_thresh);
       if isempty(GLstable_var_idx)
         GLstable_var_idx = find(abs(GLdiff_var) < var_thresh*10);
       end

       GLstable_idx = intersect(GLstable_var_idx, GLstable_auc_idx);
       if ~isempty(GLstable_idx)
        GLStableIdx_Mat(m, sidx) = min(GLstable_idx) + 1;
       else
        GLStableIdx_Mat(m, sidx)  = min(LGstable_var_idx)+1;
       end

       GLoptimalh_Mat(m, sidx)=h_list(GLStableIdx_Mat(m, sidx) );
    end
 
end

LGstable_mode_h_vec = mode(LGoptimalh_Mat,1);  % most frequent optimal h
GLstable_mode_h_vec = mode(GLoptimalh_Mat,1);  % most frequent optimal h
method_name = { 'CCA','G-FWCCA','LG-FWCCA', 'GL-FWCCA'};
nMeth=numel(method_name);

Alltestingh_Results=cell(nMeth, nSNR);

