       Alltestingh_Results{midx, sidx}= struct(...
             'EV_Test', zeros(M, Kcomp), ...
             'RCOR_Test',zeros(M, Kcomp), ...
             'AUCs_Test',   zeros(M, 1) ...
           );
   end
end

for midx=1:nMeth

  for sidx=1:nSNR

    for m=1:M
     
     if midx<3
                 
        Alltestingh_Results{midx, sidx}.EV_Test(m,:)=results{midx, sidx, m}.EV_Test';
        Alltestingh_Results{midx, sidx}.RCOR_Test(m,:)=results{midx, sidx, m}.RCOR_Test';
        Alltestingh_Results{midx, sidx}.AUCs_Test(m)=results{midx, sidx, m}.AUCs_Test;
     elseif midx==3 
        
    %% LG
       h_idx=LGStableIdx_Mat(m, sidx);
       Alltestingh_Results{midx, sidx}.EV_Test(m,:)=LocalWeightVariantresults{midx-2, sidx, m, h_idx}.EV_Test';
       Alltestingh_Results{midx, sidx}.RCOR_Test(m,:)=LocalWeightVariantresults{midx-2, sidx, m, h_idx}.RCOR_Test';
       Alltestingh_Results{midx, sidx}.AUCs_Test(m)=LocalWeightVariantresults{midx-2, sidx, m, h_idx}.AUCs_Test;    
     elseif midx==4
     %% GL
       h_idx=GLStableIdx_Mat(m, sidx);
       Alltestingh_Results{midx, sidx}.EV_Test(m,:)=LocalWeightVariantresults{midx-2, sidx, m, h_idx}.EV_Test';
