%% =====================================================
% Supplementary Figures 1--4 : Mean test canonical component maps & 
% Figure 6 in the main text
% ======================================================

%% ============================================================
% Mean test component maps for selected SNR levels
%
% Processing order:
% 1. Find a valid reference map
% 2. Sign-align each map to the reference
% 3. Normalize each aligned map to [0,1]
% 4. Average the normalized maps
% 5. Plot all methods in one figure
% ============================================================

centerB0 = [9, 9];    szB = [6, 6];
centerQ0 = [13, 13];  szQ = [3, 3];
[RB, CB] = block_from_center(centerB0, szB, grid_size);
[RQ, CQ] = block_from_center(centerQ0, szQ, grid_size);
 
boxcar_idx = sub2ind(grid_size, RB(:), CB(:));
quadratic_idx = sub2ind(grid_size, RQ(:), CQ(:));
n=prod(grid_size);

G = zeros(n, 1);
G(boxcar_idx) = 1;
G(quadratic_idx) = 1;
G=G/max(norm(G), eps);
ground_truth_map=reshape(G,grid_size);
% Plot the first two SNR settings
nSNR_to_plot = 11;

for sidx = 1:nSNR_to_plot

    snrVal = SNR_dB_list(sidx);

    for comp_k = 1:2

        mean_maps_norm = nan(prod(grid_size), nMeth);
        nUsed_maps = zeros(nMeth,1);

        %% =====================================================
        % Compute mean map for each method
        % ======================================================

        for midx = 1:nMeth

            maps_norm = nan(prod(grid_size), M);
            ref_map_unit=reshape(ground_truth_map,[],1);
            %% -------------------------------------------------
            % Step 2: Sign-align and normalize each map to [0,1]
            % --------------------------------------------------

            for m = 1:M

                R = AlltestingCCAmaps{midx, sidx, m};

                if isempty(R) || ~isstruct(R) || ...
                        ~isfield(R, 'Comp1_Test')
                    continue;
                end

                if size(R.Comp1_Test, 2) < comp_k
                    continue;
                end
                map = R.Comp1_Test(:, comp_k);
                if numel(map) ~= prod(grid_size) || ...
                        isempty(map) || any(~isfinite(map))
                    continue;
                end
                % Normalize this map  to [0,1]
                min_val = min(map);
                max_val = max(map);
                map_norm =(map - min_val) / (max_val - min_val);
             
                if map_norm'* ref_map_unit < 0
                    map_norm = -map_norm;
                end

                maps_norm(:,m) = map_norm;
            end

            %% -------------------------------------------------
            % Step 3: Average normalized maps
            % --------------------------------------------------

            valid_map_cols = ~all(isnan(maps_norm), 1);
            nUsed_maps(midx) = sum(valid_map_cols);

            if nUsed_maps(midx) == 0

                warning(['No valid maps were used for method %s, ' ...
                         'SNR = %.1f dB, direction %d.'], ...
                    method_name{midx}, snrVal, comp_k);

                continue;
            end

            mean_maps_norm(:,midx) = ...
                mean(maps_norm(:,valid_map_cols), 2, 'omitnan');

        end  % end method loop

        %% =====================================================
        % Step 4: Plot all methods after calculations are complete
        % ======================================================
        % Font sizes
        fs_axis   = 24;
        fs_title  = 26;
        fs_cb     = 26;

        fig = figure( ...
            'Name', sprintf('MeanMaps_SNR_%+gdB_Comp_%d', ...
                snrVal, comp_k), ...
            'Units', 'inches', ...
            'Position', [1 1 10 4], ...
            'Color', 'w');

        tl = tiledlayout(1, nMeth, ...
            'TileSpacing', 'compact', ...
            'Padding', 'compact');

        for midx = 1:nMeth

            ax = nexttile;

            if all(isnan(mean_maps_norm(:,midx)))

                axis(ax, 'off');

                text(ax, 0.5, 0.5, 'No valid map', ...
                    'Units', 'normalized', ...
                    'HorizontalAlignment', 'center', ...
                    'FontSize', fs_title);

                title(ax, method_name{midx}, ...
                    'Interpreter', 'none', ...
                    'FontSize', fs_title , ...
                    'FontWeight', 'bold');

                continue;
            end

            imagesc(ax, ...
                reshape(mean_maps_norm(:,midx), grid_size), ...
                [0 1]);

            axis(ax, 'image', 'off');

            title(ax, sprintf('%s', ...
                method_name{midx}), ...
                'Interpreter', 'latex', ...
                'FontSize', fs_title , ...
                'FontWeight', 'bold');

        end

        colormap(fig, parula);

        % Shared colorbar
        cb = colorbar;
        cb.Layout.Tile = 'east';
        cb.Label.String = 'Normalized index';
        cb.Label.Interpreter = 'none';
        cb.Label.FontSize = fs_cb;
        cb.Ticks = 0:0.2:1;
        cb.FontSize = fs_axis;

        set(fig, 'PaperPositionMode', 'auto');

        % Save PDF
        save_figure_PDFformat(fig, output_dir);

    end  % end component loop

end  % end SNR loop


