%%  ============================================================
%Figure 7 (main): Bandwidth selection at SNR = 0:
%training/testing AUC and local variance across
%bandwidths for LG-FWCCA and GL-FWCCA.
%
% Figure a: Train/Test AUC vs h
% Figure b: Local average variance vs h
%% ============================================================

%% ---------------- Settings ----------------
local_method_name = {'LG-FWCCA','GL-FWCCA'};
nLocalMeth = numel(local_method_name);

snrTarget = 0;
sidx0 = find(SNR_dB_list == snrTarget, 1);

if isempty(sidx0)
    error('SNR = 0 was not found in SNR_dB_list.');
end

% If M is not reliable, infer from the result cell
M_local = size(LocalWeightVariantresults, 3);
n_h = numel(h_list);

%% ---------------- Storage ----------------
mean_AUC_train = nan(nLocalMeth, n_h);
std_AUC_train  = nan(nLocalMeth, n_h);

mean_AUC_test = nan(nLocalMeth, n_h);
std_AUC_test  = nan(nLocalMeth, n_h);

mean_LocalVar = nan(nLocalMeth, n_h);
std_LocalVar  = nan(nLocalMeth, n_h);

%% ---------------- Compute summaries ----------------
for midx = 1:nLocalMeth

    for h_idx = 1:n_h

        auc_train_vec = nan(M_local,1);
        auc_test_vec  = nan(M_local,1);
        localvar_vec  = nan(M_local,1);

        for m = 1:M_local

            R = LocalWeightVariantresults{midx, sidx0, m, h_idx};

            if isempty(R)
                continue;
            end

            if isfield(R, 'AUCs_Train')
                auc_train_vec(m) = R.AUCs_Train;
            end

            if isfield(R, 'AUCs_Test')
                auc_test_vec(m) = R.AUCs_Test;
            end

            if isfield(R, 'AvgLocalVals')
                localvar_vec(m) = R.AvgLocalVals;
            end
        end

        mean_AUC_train(midx,h_idx) = mean(auc_train_vec, 'omitnan');
        std_AUC_train(midx,h_idx)  = std(auc_train_vec, 'omitnan');

        mean_AUC_test(midx,h_idx) = mean(auc_test_vec, 'omitnan');
        std_AUC_test(midx,h_idx)  = std(auc_test_vec, 'omitnan');

        mean_LocalVar(midx,h_idx) = mean(localvar_vec, 'omitnan');
        std_LocalVar(midx,h_idx)  = std(localvar_vec, 'omitnan');
    end

end



%% ============================================================
% Figure--Bandwidth : Train/Test AUC
% ============================================================

fs_axis    = 22;
fs_label   = 20;
fs_title   = 24;
fs_legend  = 22;

% Colors are allowed visually, but line style + marker distinguish methods/curves
trainauccolors = [ ...
    1.0   0.6   0.3;      % LG-FWCCA
    0.494 0.184 0.556];   % GL-FWCCA
testauccolors = [ ...
    0.5   0.8   0.3;      % LG-FWCCA
    0.2   0.3   0.9];   % GL-FWCCA

% Train/Test styles
trainLineStyle = '-';
testLineStyle  = '--';

trainMarker = 's';   % square
testMarker  = '^';   % triangle

% small x shifts to reduce overlap
shift_train = -0.035;
shift_test  =  0.035;

for midx = 1:nLocalMeth


fig = figure( ...
    'Name', sprintf('BandwidthSelection_AUC_%s_SNR_%+ddB', ...
            strrep(local_method_name{midx}, '-', '_'), snrTarget), ...
    'Color', 'w', ...
    'Units', 'inches', ...
    'Position', [1 1 5 4.8]);
 ax = nexttile;
     hold(ax, 'on');
     
    % Train AUC
    errorbar(ax, h_list + shift_train, ...
        mean_AUC_train(midx,:), ...
        std_AUC_train(midx,:), ...
        'LineStyle', trainLineStyle, ...
        'LineWidth', 2.5, ...
        'Color', trainauccolors(midx,:), ...
        'Marker', trainMarker, ...
        'MarkerSize', 9, ...
        'MarkerFaceColor', 'w', ...
        'MarkerEdgeColor', trainauccolors(midx,:), ...
        'CapSize', 7, ...
        'DisplayName', 'Train AUC');
    

    % Test AUC
    errorbar(ax, h_list + shift_test, ...
        mean_AUC_test(midx,:), ...
        std_AUC_test(midx,:), ...
        'LineStyle', testLineStyle, ...
        'LineWidth', 2.5, ...
        'Color', testauccolors(midx,:), ...
        'Marker', testMarker, ...
        'MarkerSize', 9, ...
        'MarkerFaceColor', 'w', ...
        'MarkerEdgeColor', testauccolors(midx,:), ...
        'CapSize', 7, ...
        'DisplayName', 'Test AUC');

    xlabel(ax, 'Bandwidth \(h\)', ...
        'Interpreter', 'latex', ...
        'FontSize', fs_label);

    ylabel(ax, 'Mean AUC', ...
        'FontSize', fs_label);

    title(ax, sprintf('%s',  local_method_name{midx}), ...
        'FontSize', fs_title, ...
        'FontWeight', 'bold');

    legend(ax, ...
        'Location', 'southeast', ...
        'FontSize', fs_legend, ...
        'Interpreter', 'none');

    grid(ax, 'on');
    box(ax, 'on');

    xlim(ax, [min(h_list)-0.15, max(h_list)+0.15]);
    ylim(ax, [0.70 1.02]);

    xticks(ax, h_list);

    set(ax, ...
        'FontSize', fs_axis, ...
        'LineWidth', 1.5);

    save_figure_PDFformat(fig, output_dir);
end





